      padding: 14px;
    }
    .kpi .label { color: var(--muted); font-size: .85rem; }
    .kpi .value { font-size: 1.6rem; font-weight: 700; color: var(--accent); margin: 6px 0 2px; }
    .kpi .sub { color: var(--muted); font-size: .82rem; }
    .grid-2 {
      display: grid;
      grid-template-columns: 1.25fr 1fr;
      gap: 14px;
      margin-top: 12px;
    }
    .grid-2-eq {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 14px;
      margin-top: 12px;
    }
    .chart-wrap { background: var(--panel); border: 1px solid var(--border); border-radius: 12px; padding: 12px; }
    canvas { width: 100% !important; height: 320px !important; }
