      width: 100%;
      border-collapse: collapse;
      background: var(--panel);
      border: 1px solid var(--border);
      border-radius: 10px;
      overflow: hidden;
    }
    th, td { padding: 8px 10px; border-bottom: 1px solid #26345e; text-align: left; font-size: .92rem; }
    th { color: var(--accent-2); background: var(--panel-2); }
    tr:last-child td { border-bottom: none; }
    .note { color: var(--muted); font-size: .9rem; }
    .pill { display: inline-block; padding: 3px 8px; border-radius: 999px; border: 1px solid var(--border); color: var(--accent-3); font-size: .78rem; margin-right: 6px; }
    .takeaways li { margin-bottom: 6px; }
    .footer { margin-top: 22px; color: var(--muted); font-size: .82rem; }
    @media (max-width: 980px) {
      .kpi-grid { grid-template-columns: 1fr 1fr; }
      .grid-2, .grid-2-eq { grid-template-columns: 1fr; }
    }
